-- =====================================================================
-- GUS-242 step 1c — seed the first-level region tier of geo_entities.
--
-- Source: ISO 3166-2 first-level divisions (3,590) as the KEY, with the
-- Wikidata Q-id as the cross-reference for 3,570 of them.
--
-- WHY THE ISO CODE IS THE KEY AND NOT THE Q-ID: the 16 divisions with
-- no Wikidata item are still real places and still belong in the
-- reference tier, so they are seeded with the ISO code and a NULL
-- wikidata_id. A wrong Q-id is worse than a null one (GUS-232).
--
-- WHY ONLY FIRST-LEVEL: cities are seeded on demand, per researched
-- dish. The 1,367 ISO second-level divisions and the 420 P300 codes
-- that are in no ISO list are deliberately NOT in this tier.
--
-- THE 65 DUPLICATED CODES were resolved by rule, not by hand:
--   * a 'former municipality' loses to the current 'municipality'
--   * 'region of X' beats 'district of X' (a first-level division is
--     the country's top-level unit)
--   * an administrative unit beats a physical feature (TV-NIT: the
--     Niutao Island Council, not the island)
--
-- No descriptions are written: a region's name is a fact, and the rule is
-- no imported prose. entity_type is 'region'; parent_id points at the
-- country.
--
-- Generated 2026-10-28T05:38:51Z
-- =====================================================================

