JOIN geo_entities g ON g.iso_code = substr(v.iso_code, 1, 2) AND g.entity_type = 'country'
WHERE NOT EXISTS (SELECT 1 FROM geo_entities x WHERE x.iso_code = v.iso_code);

-- The Wikidata cross-reference, matched on the ISO code.
--
-- THE 26 DUAL-CODED PLACES GET A NULL Q-ID. A place that is both an ISO
-- 3166-1 country and an ISO 3166-2 region - Hong Kong is HK and CN-HK,
-- Puerto Rico is PR and US-PR - is ONE place with ONE Wikidata item, so
-- only one row can carry the cross-reference. The COUNTRY row keeps it
-- (seeded in step 1b) and the region row keeps its ISO 3166-2 code, so
-- it stays addressable as a place reference. A null Q-id is better than
-- a wrong one.
UPDATE geo_entities g
   SET wikidata_id = v.wikidata_id
