-- ---------------------------------------------------------------------
-- Report
-- ---------------------------------------------------------------------
\echo ''
\echo '=== the reference tier ==='
SELECT entity_type, count(*) AS rows,
       count(*) FILTER (WHERE wikidata_id IS NOT NULL) AS with_qid,
       count(*) FILTER (WHERE parent_id IS NOT NULL) AS with_parent
FROM geo_entities GROUP BY entity_type ORDER BY entity_type;

\echo '=== the largest first-level sets ==='
SELECT substr(g.iso_code, 1, 2) AS country, count(*) AS regions
FROM geo_entities g WHERE g.entity_type = 'region'
GROUP BY 1 ORDER BY regions DESC LIMIT 12;

\echo '=== the 16 with no Wikidata item (ISO code is the key, Q-id is null) ==='
SELECT g.iso_code, g.name, p.iso_code AS country_code
FROM geo_entities g
LEFT JOIN geo_entities p ON p.id = g.parent_id
WHERE g.entity_type = 'region' AND g.wikidata_id IS NULL
ORDER BY g.iso_code;

\echo '=== no region lacks a parent country ==='
SELECT count(*) AS regions_without_parent
FROM geo_entities g
WHERE g.entity_type = 'region' AND g.parent_id IS NULL;

\echo '=== every region parent is a country ==='
SELECT count(*) AS bad_parents
FROM geo_entities g JOIN geo_entities p ON p.id = g.parent_id
WHERE g.entity_type = 'region' AND p.entity_type <> 'country';

COMMIT;
